  if (m.varal) { VARAL.x0 += dx; VARAL.x1 += dx; VARAL.y += dy; } else if (m.arr) { m.arr()[m.i][0] = x; m.arr()[m.i][1] = y; } else { m.o().x = x; m.o().y = y; }
