  item("Óleo da lanterna", "Enche a lanterna e as lamparinas", 5, R.oleo < 100, () => { R.oleo = 100; });
  if (R.aguaMax < 10 + (reparoOk("poco") ? 2 : 0)) item("Regador grande", "Carrega 10 de água", 25, true, () => { R.aguaMax = 10 + (reparoOk("poco") ? 2 : 0); R.agua = R.aguaMax; });
  else if (R.aguaMax < 16 + (reparoOk("poco") ? 2 : 0)) item("Regador de lata", "Carrega 16 de água", 70, true, () => { R.aguaMax = 16 + (reparoOk("poco") ? 2 : 0); R.agua = R.aguaMax; });
  if (R.vel < 3.6) item("Botas de borracha", "Anda e corre mais rápido", 40, true, () => { R.vel = 3.75; });
  if (!R.lanternaBoa) item("Lanterna reforçada", "Ilumina mais e gasta menos óleo", 35, true, () => { R.lanternaBoa = true; });
  if (!R.peneira) item("Peneira", "Para pegar o Saci no redemoinho", 20, true, () => { R.peneira = true; });
  Object.entries(PLANTAS).forEach(([k, p]) => { if (p.custo && !R.sementes.includes(k) && (!p.estufa || estufaPronta())) item(`Sementes de ${p.nome.toLowerCase()}`, `Vende por ${p.preco} cada${p.estufa ? " · só na estufa" : ""}`, p.custo, true, () => { R.sementes.push(k); }); });
  const nomesPecas = PECAS;
  if (R.pecas < 3) item(`Peça: ${nomesPecas[R.pecas][0]}`, `Caminhonete ${R.pecas}/3 · leve até ela para ir embora`, nomesPecas[R.pecas][1], true, () => { R.pecas++; }, true);
