  if (R.lugar === "lagoa") return objetivoLagoa();
  if (R.viagem) return "viajando de trem"; if (R.lugar === "serra") return objetivoSerra(); if (R.lugar === "floresta") return objetivoFloresta(); if (R.lugar === "grota") return objetivoGrota();
