  if (R.cachorro && (R.cachorro.fase === "lobo" || R.cachorro.fase === "vira")) p = 1;
  if (R.vulto) p = Math.max(p, .5); if (R.pisadeira) p = 1;
  const a = R.aranha; if (a.fase === "anda") p = Math.max(p, .55 + a.alerta * .45); if (a.fase === "ataque") p = 1;
