  const alvo = (P.dentro || (P.lugar || "sitio") !== "sitio") ? { x: CASA.porta.x, y: CASA.porta.y + 1.3 } : P.eu, pulo = .5 + .9 * Math.abs(Math.sin(e.t * 4));
  irAte(e, alvo, 2.1 * pulo, dt); if (e.t % .55 < dt) S.palha(e.x, e.y);
