function conversarBx(n) { R.conv = R.conv || {}; const i = R.conv[n.id] || 0, lista = n.conversas[i] || [n.extra[Math.floor(Math.random() * n.extra.length)]]; R.conv[n.id] = i + 1; falar(lista, n.id === "zefa" && i === 4 ? () => lerAchadoBx("zefa") : null, n.nome); }
