  FERR.forEach(([k, n, p, d]) => { if (!(inv["f:" + k] > 0)) it(n, d + " · ferramenta, é sua pra sempre", p, "f:" + k, 1); });
  MATERIAIS.forEach(([k, n, p, q, d]) => it(n, d + ` · você tem ${inv["x:" + k] || 0}`, p, "x:" + k, q));
  MELHORIAS.forEach(mh => { if (!casaTem(mh.k) && !(inv["r:" + mh.k] > 0)) it(mh.nome, mh.desc + " · coloque em \"Arrumar a casa\", na frente da casa", mh.preco, "r:" + mh.k, 1); });
