  const mh = MELHORIAS.find(z => z.k === k); if (mh) { if (casaTem(k)) { delete R.deco.casa["m_" + k]; inv["r:" + k] = (inv["r:" + k] || 0) + 1; salvarDeco(); return true; } if (!(inv["r:" + k] > 0) || (mh.precisa || []).some(p => !casaOk(p))) return false; inv["r:" + k]--; R.deco.casa["m_" + k] = 1; salvarDeco(); efeito(mh.nome + " no lugar!", "#f2c94a"); return true; }
