const SEGREDOS = [
  { k: "tumulo", onde: "a lápide sem nome do cemitério", txt: "Debaixo da lápide sem nome, uma caixinha de lata enferrujada. Dentro: um laço de fita vermelha, um dente de leite e um papel: \"Aqui não tem ninguém enterrado. Aqui eu enterrei o meu medo, pra ele não me seguir. — B., 1966\"" },
  { k: "bau", onde: "o baú do sótão do celeiro", txt: "Dentro do baú: um vestido de noiva amarelado, um maço de cartas amarradas com barbante e um envelope gordo de dinheiro velho trocado por moeda nova. Na primeira carta: \"Bené, se você está lendo, é porque eu não voltei. Usa esse dinheiro pra tirar a menina daqui. — Sebastião\"" },
  { k: "cripta", onde: "o livro de batismos da cripta", txt: "Livro de batismos da Igreja de Santa Luzia. \"Benedita, 1941. Dora, 1943. Marcos, 1970.\" Na última linha, com tinta ainda brilhando, como se tivesse sido escrita hoje: \"Yasmin, batizada na mata. Padrinho: o Dono.\"" }];
const segredosAchados = () => { try { return JSON.parse(ls("roca_segredos") || "[]"); } catch (e) { return []; } };
function lerSegredo(k) {
  const a = SEGREDOS.find(z => z.k === k); if (!a) return; const l = segredosAchados(), nova = !l.includes(k); if (nova) { l.push(k); ls("roca_segredos", JSON.stringify(l)); ls("roca_seg_" + k, 1); }
  painelAberto = true; el.rcPainel.hidden = false;
  el.rcPainel.innerHTML = `<div class="rc-caixa rc-diario"><h2>Segredos do sítio</h2><p style="font-size:12px;opacity:.7">Achado: ${a.onde} · ${l.length}/${SEGREDOS.length}</p><p style="font-style:italic">${escH(a.txt)}</p><div class="rc-linha"><button type="button" class="rc-op dest" id="rcFechar">Guardar</button></div></div>`;
  document.getElementById("rcFechar").addEventListener("click", () => { fecharPainel(); hud(); });
  if (nova) { S.colher(); tocarTom(70, 1.4, { vol: .2, ate: 40 }); }
}
