/* ---------- a Lagoa Grande: depois da Baixada, pela trilha do oeste ----------
   Uma lagoa enorme pra andar de barquinho (você controla: o joystick aponta pra onde o barco vira e rema;
   "correr" é remar forte). Ilhas: o Farol (dá pra acender), a Capelinha, a Ilha das Garças, a palafita do
   Seu Bento (pescador, vende remo bom, lanterna de proa e tinta pro barco), a Figueira e a ilhota do tesouro.
   Na água: naufrágio, redemoinho, troncos boiando, patos, vitórias-régias e pontos de pesca.
   De noite, a Boiuna (cobra grande) caça barco na água FUNDA: fique no raso (água clara, perto da terra)
   ou acenda o farol antes da noite, que ela fica no fundo a noite inteira. */
const LGW = 144, LGH = 108, LAGO_C = { x: 72, y: 54, rx: 64, ry: 48 };
const ILHAS = [
  { k: "farol", nome: "Ilha do Farol", x: 31, y: 24, r: 7, s: 1.3 }, { k: "capela", nome: "Ilha da Capelinha", x: 78, y: 20, r: 4.4, s: 2.1 },
  { k: "garcas", nome: "Ilha das Garças", x: 40, y: 80, r: 7.2, s: .7 }, { k: "bento", nome: "Ilha da Palafita", x: 105, y: 80, r: 5.6, s: 3.3 },
  { k: "tesouro", nome: "Ilhota da Pedra", x: 118, y: 32, r: 2.7, s: 4.1 }, { k: "figueira", nome: "Ilha da Figueira", x: 71, y: 86, r: 4.2, s: 5.2 },
  { k: "esqueleto", nome: "Banco do Esqueleto", x: 54, y: 42, r: 2.8, s: 6.1 }, { k: "pedras", nome: "Ilha das Pedras", x: 104, y: 30, r: 3.4, s: 7.3 }];
const raioIlha = (I, a) => I.r * (1 + .13 * Math.sin(3 * a + I.s) + .07 * Math.sin(5 * a + I.s * 2) + .04 * Math.sin(9 * a + I.s * 3));
const naIlhaLg = (x, y) => ILHAS.find(I => { const dx = x - I.x, dy = y - I.y, d = Math.hypot(dx, dy); return d < I.r * 1.3 && d < raioIlha(I, Math.atan2(dy, dx)); });
const raioLago = a => 1 + .05 * Math.sin(4 * a + .5) + .03 * Math.sin(7 * a + 1.2) + .02 * Math.sin(13 * a);
function dentroLago(x, y) { const dx = (x - LAGO_C.x) / LAGO_C.rx, dy = (y - LAGO_C.y) / LAGO_C.ry, a = Math.atan2(dy, dx); return Math.hypot(dx, dy) < raioLago(a) && Math.abs(dx) ** 4 + Math.abs(dy) ** 4 < 1.15; }
const aguaLg = (x, y) => dentroLago(x, y) && !naIlhaLg(x, y);
const PIER_LG = { x0: 130.2, x1: 138.6, y: 54, l: 1 }, PIER_BENTO = { x0: 109.6, x1: 113.6, y: 81.4, l: .8 }, PIER_FAROL = { x0: 37, x1: 41, y: 26.4, l: .8 };
