const NAUFRAGIO = { x: 64.5, y: 58.5 }, REDEMOINHO = { x: 96, y: 56, r: 4.2 }, CHEGADA_LG = { x: 141, y: 55.2 }, POCAO = { x: 30, y: 54, r: 12 };
