  // profundidade (água até a terra) e praia (terra até a água), numa grade de meio tile
  const GW = LGW * 2, GH = LGH * 2, dist2 = new Float32Array(GW * GH).fill(99), distT = new Float32Array(GW * GH).fill(99), q = [], qt = [];
  for (let y = 0; y < GH; y++) for (let x = 0; x < GW; x++) { const i = y * GW + x; if (!aguaLg(x / 2 + .25, y / 2 + .25)) { dist2[i] = 0; q.push(i); } else { distT[i] = 0; qt.push(i); } }
  const bfs = (D, Q) => { for (let h = 0; h < Q.length; h++) { const i = Q[h], x = i % GW, y = (i / GW) | 0, d = D[i] + .5; if (d > 12) continue; for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { const nx = x + dx, ny = y + dy; if (nx < 0 || ny < 0 || nx >= GW || ny >= GH) continue; const j = ny * GW + nx; if (D[j] > d) { D[j] = d; Q.push(j); } } } };
