  const praia = (x, y) => { const gx = Math.floor(x * 2), gy = Math.floor(y * 2); if (gx < 0 || gy < 0 || gx >= GW || gy >= GH) return 99; return distT[gy * GW + gx]; };
  // árvores: na margem e nas ilhas (longe da areia)
