  const coqueiros = []; for (let i = 0; i < 2000 && coqueiros.length < 46; i++) { const x = r2() * LGW, y = r2() * LGH, p = praia(x, y); if (p < 1.2 || p > 2.2 || noPierLg(x, y) || Math.hypot(x - CHEGADA_LG.x, y - CHEGADA_LG.y) < 4) continue; coqueiros.push({ x, y, k: r2(), a: (r2() - .5) * .5 }); }
  const junco = [], vitoria = [], aguape = []; for (let i = 0; i < 12000 && junco.length < 560; i++) { const x = r2() * LGW, y = r2() * LGH, f = fundo(x, y); if (!aguaLg(x, y) || f > 1.6 || f < .5 || noPierLg(x, y) || Math.hypot(x - PIER_LG.x0, y - PIER_LG.y) < 3) continue; if (r2() < .55) junco.push({ x, y, k: r2() }); else if (r2() < .5 && f > .9) vitoria.push({ x, y, r: .32 + r2() * .28, fl: r2() < .25, a: r2() * 6 }); else aguape.push({ x, y, k: r2() }); }
  // coisas na areia: conchas, pedrinhas, galhos que a água trouxe, pegadas e caranguejos
  const areia = []; for (let i = 0; i < 20000 && areia.length < 420; i++) { const x = r2() * LGW, y = r2() * LGH, p = praia(x, y); if (p > 1.4 || p <= .25 || noPierLg(x, y)) continue; const r = r2(); areia.push({ x, y, t: r < .35 ? "concha" : r < .65 ? "pedra" : r < .8 ? "galho" : r < .9 ? "alga" : "carang", k: r2(), a: r2() * 6 }); }
