  arv.forEach(a => { const k = Math.floor(a.x) + "," + Math.floor(a.y); if (!cel.has(k)) cel.set(k, []); cel.get(k).push(a); });
  const ossos = []; for (let i = 0; i < 2000 && ossos.length < 26; i++) { const a = r() * PI * 2, d = r() * (NINHO_GT.r - 1.2), x = NINHO_GT.x + Math.cos(a) * d, y = NINHO_GT.y + Math.sin(a) * d * .85; ossos.push({ x, y, a: r() * PI, k: r() }); }
  const cogu = []; for (let i = 0; i < 3000 && cogu.length < 60; i++) { const x = r() * GTW, y = 3 + r() * (GTH - 4); if (naTrilha(x, y) < 1.2) continue; cogu.push({ x, y, k: r() }); }
