  const troncos = []; for (let i = 0; i < 2000 && troncos.length < 10; i++) { const x = 3 + r() * (GTW - 6), y = 4 + r() * (GTH - 6); if (naTrilha(x, y) < 2.2 || Math.hypot(x - NINHO_GT.x, (y - NINHO_GT.y) * 1.15) < NINHO_GT.r + 1) continue; troncos.push({ x, y, a: (r() - .5) * .6, l: 1.8 + r() * 1.4 }); }
