  // o ninho: terra pelada e pisoteada, com fio de teia velho por cima e marcas de pata
  const N = NINHO_GT, gn = g.createRadialGradient(N.x * P, N.y * P, P, N.x * P, N.y * P, (N.r + 1) * P); gn.addColorStop(0, "#3e3426"); gn.addColorStop(.75, "#2e2818"); gn.addColorStop(1, "rgba(20,26,14,0)"); g.fillStyle = gn; g.beginPath(); g.ellipse(N.x * P, N.y * P, (N.r + 1) * P, (N.r + 1) * .86 * P, 0, 0, 7); g.fill();
  for (let i = 0; i < 800; i++) { sd = semInd(i + 25e6); const a = r2() * 6.283, d = r2() * (N.r - .6), x = (N.x + Math.cos(a) * d) * P, y = (N.y + Math.sin(a) * d * .86) * P; if (!vis(x, y)) continue; g.fillStyle = i % 3 ? "rgba(14,10,6,.32)" : "rgba(120,100,70,.22)"; g.beginPath(); g.ellipse(x, y, 2 + r2() * 5, 1.4 + r2() * 3, r2() * 3, 0, 7); g.fill(); }
  for (let i = 0; i < 40; i++) { sd = semInd(i + 26e6); const a = r2() * 6.283, d = r2() * (N.r - 1.5), x = (N.x + Math.cos(a) * d) * P, y = (N.y + Math.sin(a) * d * .86) * P; if (!vis(x, y, 30)) continue; g.fillStyle = "rgba(10,6,2,.45)"; for (let k = 0; k < 3; k++) { g.beginPath(); g.ellipse(x + k * 5 - 5, y - Math.abs(k - 1) * 3, 2, 3.4, (k - 1) * .4, 0, 7); g.fill(); } } // marcas das patas
