const livreSitioP = (x, y) => { const tx = Math.floor(x), ty = Math.floor(y); if (ty < 0 || ty >= MH || tx < 0 || tx >= MW || R.solido[ty][tx]) return false; for (const [x0, y0, x1, y1] of R.caixas) if (x > x0 && x < x1 && y > y0 && y < y1) return false; return true; };
