function voltarSitio() { R.lugar = "sitio"; R.predio = null; R.eu.x = SX(25.2); R.eu.y = MH - 2.4; cam.x = SX(25.2); cam.y = MH - 6; R.fade = 1; S.porta(); hud(); }
